llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Loperamide, a 2,2-diphenylbutanamide with a basic amine and hydroxyl, has an absolute oral bioavailability of only 0.3% in humans due to P-gp efflux and first-pass metabolism; the query shares the same diphenylacetamide/butanamide pharmacophore, basic pyrrolidine/piperidine, and hydroxyl, making this low-F liability directly transferable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Terfenadine, a lipophilic diphenyl-substituted basic amine, has absolute oral bioavailability below 2% in humans due to extensive CYP3A4 first-pass metabolism; the query's three phenyl rings and basic amine predict a similar high first-pass clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Phenoperidine, a lipophilic phenylpiperidine with a basic amine and alcohol, shows systemic bioavailability of only about 10-14% after oral dosing, supporting low F for the query's similar lipophilic basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fentanyl, a tertiary amide opioid with a basic piperidine, has absolute oral bioavailability of 32% when swallowed, above the 20% threshold; however, it is smaller, less lipophilic, and lacks the diphenylacetamide/hydroxyl features of the query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Fexofenadine has an absolute oral bioavailability of 41% at a microdose, but its zwitterionic acid/amine structure and minimal metabolism differ substantially from the query's neutral, lipophilic amide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ebastine, a lipophilic BCS-II antihistamine, achieves about 40% oral bioavailability, suggesting that lipophilic basic amines can exceed 20%; however, its ketone/ether scaffold and metabolic profile are not closely analogous to the query's diphenylacetamide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the query's diphenylacetamide/basic amine/hydroxyl pharmacophore closely matches loperamide and terfenadine, both with very low absolute F due to P-gp efflux and first-pass metabolism; high-F analogues are less transferable due to structural differences.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "P-gp and CYP3A4 substrate status of the query is not experimentally confirmed.",
    "Conflicting evidence from fentanyl, fexofenadine, and ebastine with F 30-41% leaves uncertainty.",
    "Solubility and intestinal permeability of the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

